\begin{ex}%[8H3V3]
\immini[thm]{
Cho hình bình hành  ${EFGH}$. Có ${I, J, Q, K}$ lần lượt là trung điểm của ${ EF, FG, GH, EH }$. Chọn khẳng định sai trong các khẳng định sau?

\choice
{ ${IJQK }$ là hình bình hành   }
   { \True ${JQHF}$ là hình thang cân  }
     { $IK=JQ$  }
    { $IJ=QK$ }
}{
\begin{tikzpicture}
            \coordinate (P) at (2.5, 1);
            \coordinate (D) at (-3, 0);
            \coordinate (C) at (2, 0);
            \coordinate (B) at (3, 2);
            \coordinate (A) at (-2, 2);
            \coordinate (M) at (-5/2, 1);
            \coordinate (N) at (1/2, 2);
             \coordinate (Q) at (-1/2, 0);
            % Vẽ tứ giác
            \draw[thick] (M) -- (N)--(P) -- (Q)--(M);
            \draw[thick] (A) -- (B) -- (C) -- (D) -- (A);

            % Ghi nhãn các điểm
            \node[above left] at (M) {$I$};
            \node[above right] at (B) {$F$};
            \node[below right] at (C) {$G$};
            \node[below left] at (D) {$H$};
            \node[above left] at (A){$E$};
            \node[above] at (N) {$J$};
            \node[above right] at (P) {$Q$};
             \node[below] at (Q) {$K$};
    \end{tikzpicture}
}
\loigiai{
$ EF=GH \Rightarrow \dfrac{1}{2}EF=\dfrac{1}{2}GH=IE=IF=GQ=QH$\\
và $FG=EH \Rightarrow \dfrac{1}{2}FG=\dfrac{1}{2}EH=JF=GJ=KE=KH $\\
Xét $\Delta {FIJ}$ và $\Delta {HQK}$ có\\
$FJ=HK=\dfrac{1}{2}FG=\dfrac{1}{2}EH $\\
$\widehat{F} = \widehat{H}$, $IF=QH= \dfrac{1}{2}EF =\dfrac{1}{2} GH$\\
$\Rightarrow \Delta {FIJ} =\Delta {HQK}$ (c-g-c) $\Rightarrow IJ=QK $\\
CM tương tự $IK=JQ$ suy ra ${IJQK }$ là hình bình hành\\
Khẳng định sai là ${JQHF}$ là hình thang cân vì chưa đủ cơ sở để kết luận.
}\end{ex}

